#include <M5StickCPlus2.h>

#define IN1 26
#define IN2 0
#define ENA 2

void setup() {
  M5.begin();
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(ENA, OUTPUT);

  M5.Lcd.setRotation(3);
  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setTextColor(WHITE);
  M5.Lcd.println("Motor Control Ready");
}

void loop() {
  M5.update();

  if (M5.BtnA.wasPressed()) {
    digitalWrite(IN1, HIGH);
    digitalWrite(IN2, LOW);
    analogWrite(ENA, 200);
    M5.Lcd.println("Motor Forward");
  }

  if (M5.BtnB.wasPressed()) {
    digitalWrite(IN1, LOW);
    digitalWrite(IN2, HIGH);
    analogWrite(ENA, 200);
    M5.Lcd.println("Motor Reverse");
  }
}

